def clean(df):
    df['Category'] = df['Category'].str.strip()
    df['Region'] = df['Region'].str.strip().replace({'Suoth': 'South', 'Nort': 'North'})
    return df.dropna(subset=['Region'])

def answer(df):
    electronics_df = df[df['Category'] == 'Electronics']
    revenue_by_region = electronics_df.groupby('Region')['Revenue'].sum().to_dict()
    return revenue_by_region}
